import{_ as e,H as a,f as d,i as o}from"./chunks/framework.Cvt1eIE0.js";const C=JSON.parse('{"title":"第一章：Claude Code 是什么","description":"了解 Claude Code 的基本概念和使用场景","frontmatter":{"title":"第一章：Claude Code 是什么","description":"了解 Claude Code 的基本概念和使用场景"},"headers":[],"relativePath":"guide/1-getting-started/1-what-is-claude-code.md","filePath":"guide/1-getting-started/1-what-is-claude-code.md"}'),l={name:"guide/1-getting-started/1-what-is-claude-code.md"};function r(i,t,s,n,u,c){return a(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="第一章-claude-code-是什么" tabindex="-1">第一章：Claude Code 是什么 <a class="header-anchor" href="#第一章-claude-code-是什么" aria-label="Permalink to &quot;第一章：Claude Code 是什么&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">学习目标</p><p>学完这章，你会理解 Claude Code 能做什么，不能做什么。</p></div><h2 id="claude-code-是命令行工具-不是网页聊天" tabindex="-1">Claude Code 是命令行工具，不是网页聊天 <a class="header-anchor" href="#claude-code-是命令行工具-不是网页聊天" aria-label="Permalink to &quot;Claude Code 是命令行工具，不是网页聊天&quot;">​</a></h2><p>Claude Code 是一个运行在<strong>终端/命令行</strong>里的工具。你通过打字和它对话，它帮你读写代码。</p><p>这和网页版的 Claude（claude.ai）不一样：</p><ul><li><strong>Claude.ai</strong>：在浏览器里聊天，适合问答、写作、分析</li><li><strong>Claude Code</strong>：在你的电脑里工作，直接读写你的代码文件</li></ul><h2 id="claude-code-能做什么" tabindex="-1">Claude Code 能做什么？ <a class="header-anchor" href="#claude-code-能做什么" aria-label="Permalink to &quot;Claude Code 能做什么？&quot;">​</a></h2><p>Claude Code 是一个 AI 编程助手，它可以：</p><ul><li><strong>读代码</strong>：帮你理解一个陌生项目的结构</li><li><strong>写代码</strong>：帮你创建新文件或修改现有代码</li><li><strong>解释代码</strong>：用自然语言解释代码在做什么</li><li><strong>调试问题</strong>：帮你找出 bug 并修复</li><li><strong>审查代码</strong>：给你代码优化建议</li><li><strong>辅助 Git</strong>：帮你写 commit message、处理合并冲突</li></ul><h2 id="claude-code-不能做什么" tabindex="-1">Claude Code 不能做什么？ <a class="header-anchor" href="#claude-code-不能做什么" aria-label="Permalink to &quot;Claude Code 不能做什么？&quot;">​</a></h2><p>它不能替你做所有事：</p><ul><li><strong>不能替你运行代码</strong>：Claude 写的代码需要你确认后手动运行</li><li><strong>不能直接访问互联网</strong>：它只能读写你本地的文件</li><li><strong>不会读心术</strong>：你需要清楚地描述你要什么</li></ul><h2 id="和-chatgpt-copilot-的区别" tabindex="-1">和 ChatGPT / Copilot 的区别 <a class="header-anchor" href="#和-chatgpt-copilot-的区别" aria-label="Permalink to &quot;和 ChatGPT / Copilot 的区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>特点</th><th>适合场景</th></tr></thead><tbody><tr><td>ChatGPT</td><td>网页聊天，什么都能问</td><td>通用问答、写文章</td></tr><tr><td>Copilot</td><td>IDE 插件，边写边补全</td><td>写代码时自动补全</td></tr><tr><td>Claude Code</td><td>命令行工具，深入项目</td><td>需要理解整个项目时</td></tr></tbody></table><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to &quot;前置知识&quot;">​</a></h2><p>本章不需要任何前置知识。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q: Claude Code 要钱吗？</strong></p><p>A: Claude Code 本身免费，但使用 Claude 的 API 需要付费。新用户有免费额度，初期够用。</p><p><strong>Q: 不会命令行能学吗？</strong></p><p>A: 当然可以！教程会从零教你基本的终端命令。</p><h2 id="下一章" tabindex="-1">下一章 <a class="header-anchor" href="#下一章" aria-label="Permalink to &quot;下一章&quot;">​</a></h2><p>下一章我们会学习如何安装 Claude Code。</p><p><a href="/guide/1-getting-started/2-installation.html">👉 第二章：安装 Claude Code</a></p>',24)])])}const p=e(l,[["render",r]]);export{C as __pageData,p as default};
